head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.procJob = "";
scwin.vListInit = true;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate);
        const usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
        cmb_PeriodTp.CBData = usrCBData; // 사용자CBData 지정

        // MaxTab_01.ActiveIndex = 1;
        await scwin.setCode();
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08011.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_ISUR_CD_onselchange
 * @description cmb_ISUR_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_onselchange = async function() {
    try {
        // 발행회사 조회시 초기에 재조회 안타게 하기 위함
        if (scwin.vListInit === false) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08011.cmb_ISUR_CD_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08011.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF08011.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08011.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_1_onheadcheckclick
 * @description grd_List_1 onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_onheadcheckclick = async function(col, colid, bCheck) {
    try {
        await $c.win.alert('grd_List.OnHeadCheckClick(' + col + ',' + colid + ',' + bCheck + ')');
        $c.lce.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08011.grd_List_1_onheadcheckclick" });
    }
};

