 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'ISU_ABBRV') {
            await scwin.openNewWin(row, dts_List_1);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08011.grd_List_1_OnDblClick" });
