 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08011.txb_ISU_CD_onblur" });
    }
};

