/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EtnInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("call");

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    scwin.vListInit = false;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += "?SCREN_ID=" + "ULDSTF08011.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnReceipt&inputMessageId=ETN_NEWLISTING_SEARCH_OUT";
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&ISU_CD=" + txb_ISU_CD.getValue();
        url += "&S_DATE=" + edt_SDate.getValue();
        url += "&E_DATE=" + edt_EDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/etn/EtnNewList.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        url += "?SCREN_ID=" + "ULDSTF08011.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnAddReceipt&inputMessageId=ETN_NEWLISTING_SEARCH_OUT";
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&ISU_CD=" + txb_ISU_CD.getValue();
        url += "&S_DATE=" + edt_SDate.getValue();
        url += "&E_DATE=" + edt_EDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/etn/EtnNewList.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        url += "?SCREN_ID=" + "ULDSTF08011.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnlosslmtReceipt&inputMessageId=ETN_NEWLISTING_LOSSLMT_SEARCH_OUT";
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&ISU_CD=" + txb_ISU_CD.getValue();
        url += "&S_DATE=" + edt_SDate.getValue();
        url += "&E_DATE=" + edt_EDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_3",
            action : "/etn/EtnNewList.do",
            ref : "",
            target : "dts_List_3=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        url += "?SCREN_ID=" + "ULDSTF08011.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnlosslmtAddReceipt&inputMessageId=ETN_NEWLISTING_LOSSLMT_SEARCH_OUT";
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&ISU_CD=" + txb_ISU_CD.getValue();
        url += "&S_DATE=" + edt_SDate.getValue();
        url += "&E_DATE=" + edt_EDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_4",
            action : "/etn/EtnNewList.do",
            ref : "",
            target : "dts_List_4=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

