 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 함수
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        vIsurCd = arrPar[0].ISUR_CD;
    }
};

/**
 * @method
 * @name initSearchDate
 * @description 신규/추가상장의 목록검색시작일과 종료일자의 초기값 설정
 * @param {*} edtSDate edtSDate
 * @param {*} edtEDate edtEDate
 * @returns {void}
 * @hidden N
 */
scwin.initSearchDate = function(edtSDate, edtEDate) {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edtSDate.setValue('19000101');
    edtEDate.setValue($c.ut.cGetPlusDate2(vCurDate, 60));
};

/**
 * @method
 * @name getListBzTpCd
 * @description 추가상장신청시의 업무구분코드 가져오기
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.getListBzTpCd = function(str) {
    let val = '';
    if (str === LIST_BZ_TP_CD_002) {
        val = LIST_BZ_TP_CD_004;
    } else if (str === LIST_BZ_TP_CD_003) {
        val = LIST_BZ_TP_CD_005;
    }
    return val;
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
};

/**
 * @method
 * @name openNewWin
 * @description open New Win 처리
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNewWin = async function(row, dtsObj) {
    scwin.setBzProcsNo(row, dtsObj);
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        const options = {
            id: "ULDSTF08012",
            title: "종목상세화면-신규상장",
            type: "browserPopup",
            width: "1100px",
            height: "960px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/etn/ULDSTF08012.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        const options = {
            id: "ULDSTF08014",
            title: "종목상세화면-추가상장",
            type: "browserPopup",
            width: "1092px",
            height: "902px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/etn/ULDSTF08014.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        const options = {
            id: "ULDSTF08112",
            title: "종목상세화면(손실제한)-신규상장",
            type: "browserPopup",
            width: "1120px",
            height: "980px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/etn/ULDSTF08112.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        const options = {
            id: "ULDSTF08114",
            title: "종목상세화면(손실제한)-추가상장",
            type: "browserPopup",
            width: "1120px",
            height: "912px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/etn/ULDSTF08114.gfm", options);
    }
};

/**
 * @method
 * @name getDataSet
 * @description get Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.getDataSet = function() {
    let dtsObj;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dtsObj = dts_List_2;
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        dtsObj = dts_List_3;
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        dtsObj = dts_List_4;
    }
    return dtsObj;
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "신규상장목록(일반)", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "추가상장목록(일반)", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        $c.data.downloadGridViewExcel(grd_List_3, {fileName: "신규상장목록(손실제한)", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        $c.data.downloadGridViewExcel(grd_List_4, {fileName: "추가상장목록(손실제한)", type: "8"});
    }
};
